 int main(){D d[2];E* a=static_cast<A*>(&d[0]);E* b=static_cast<B*>(&d[0]);
 E* c=static_cast<A*>(&d[1]);E* e=static_cast<B*>(&d[1]);return a==b||a==c||a==e||b==c||b==e||c==e;}

